# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ÇEVRE TEMİZLİĞİ, EKOLOJİK DENGE VE ORTAK KULLANIM ALANLARI</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">1. Çevre Emaneti ve İmar Sorumluluğu</text>\n  <text x="180" y="94" text-anchor="middle" font-size="11" fill="#14532d">• Doğa, su, hava ve toprak Allah\'ın insana</text>\n  <text x="180" y="112" text-anchor="middle" font-size="11" fill="#14532d">bıraktığı kutsal birer EMANETTİR.</text>\n  <text x="180" y="136" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Rûm Suresi, 41. Ayet:</text>\n  <text x="180" y="154" text-anchor="middle" font-size="11" fill="#14532d">\'İnsanların kendi elleriyle yapıp ettikleri</text>\n  <text x="180" y="172" text-anchor="middle" font-size="11" fill="#14532d">yüzünden karada ve denizde bozulma çıktı...\'</text>\n  <text x="180" y="198" text-anchor="middle" font-size="11" fill="#14532d">• Ağaç dikmek ve çevreyi yeşertmek</text>\n  <text x="180" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">SADAKA-İ CARİYE (kesintisiz sevap) sayılır.</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">2. Ortak Alanlar ve Kul Hakkı Bilinci</text>\n  <text x="520" y="94" text-anchor="middle" font-size="11" fill="#1e3a8a">• Okul, cami, park, sokak, toplu taşıma ve</text>\n  <text x="520" y="112" text-anchor="middle" font-size="11" fill="#1e3a8a">piknik alanlarını kirletmek KUL HAKKIDIR.</text>\n  <text x="520" y="136" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">İmâtetu\'l-Ezâ (Yoldan Eziyeti Kaldırmak):</text>\n  <text x="520" y="154" text-anchor="middle" font-size="11" fill="#1e3a8a">\'İman yetmiş küsur şubedir... En alt derecesi</text>\n  <text x="520" y="172" text-anchor="middle" font-size="11" fill="#1e3a8a">yoldan eziyet veren şeyi kaldırmaktır.\'</text>\n  <text x="520" y="198" text-anchor="middle" font-size="11" fill="#1e3a8a">• Durgun ve akan suları, ağaç gölgelerini</text>\n  <text x="520" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">ve yolları kirletmek hadisle yasaklanmıştır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İBADETE HAZIRLIK: HÜKMÎ TEMİZLİK (ABDEST, GUSÜL VE TEYEMMÜM)</text>\n  <rect x="20" y="45" width="210" height="195" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="125" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">1. Abdest (Mâide, 6)</text>\n  <text x="125" y="94" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">4 Farzı Vardır:</text>\n  <text x="125" y="114" text-anchor="middle" font-size="11" fill="#164e63">1. Yüzü bir kez yıkamak</text>\n  <text x="125" y="134" text-anchor="middle" font-size="11" fill="#164e63">2. Kolları dirseklerle</text>\n  <text x="125" y="150" text-anchor="middle" font-size="11" fill="#164e63">birlikte yıkamak</text>\n  <text x="125" y="170" text-anchor="middle" font-size="11" fill="#164e63">3. Başın dörtte birini</text>\n  <text x="125" y="186" text-anchor="middle" font-size="11" fill="#164e63">mesh etmek (ıslak elle)</text>\n  <text x="125" y="206" text-anchor="middle" font-size="11" fill="#164e63">4. Ayakları topuklarla</text>\n  <text x="125" y="222" text-anchor="middle" font-size="11" fill="#164e63">birlikte yıkamak</text>\n\n  <rect x="245" y="45" width="210" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="350" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">2. Gusül (Boy Abdesti)</text>\n  <text x="350" y="94" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">3 Farzı Vardır:</text>\n  <text x="350" y="118" text-anchor="middle" font-size="11" fill="#713f12">1. Ağza su alıp boğaza</text>\n  <text x="350" y="136" text-anchor="middle" font-size="11" fill="#713f12">kadar çalkalamak (Mazmaza)</text>\n  <text x="350" y="160" text-anchor="middle" font-size="11" fill="#713f12">2. Burna su çekip</text>\n  <text x="350" y="178" text-anchor="middle" font-size="11" fill="#713f12">temizlemek (İstinşak)</text>\n  <text x="350" y="202" text-anchor="middle" font-size="11" fill="#713f12">3. Bütün vücudu kuru yer</text>\n  <text x="350" y="220" text-anchor="middle" font-size="11" fill="#713f12">kalmayacak şekilde yıkamak</text>\n\n  <rect x="470" y="45" width="210" height="195" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="575" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">3. Teyemmüm</text>\n  <text x="575" y="94" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">Su Yoksa / Kullanılamıyorsa:</text>\n  <text x="575" y="116" text-anchor="middle" font-size="11" fill="#581c87">• Temiz toprak veya toprak</text>\n  <text x="575" y="134" text-anchor="middle" font-size="11" fill="#581c87">cinsi yüzeyle alınır.</text>\n  <text x="575" y="158" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">2 Farzı Vardır:</text>\n  <text x="575" y="178" text-anchor="middle" font-size="11" fill="#581c87">1. Niyet etmek</text>\n  <text x="575" y="198" text-anchor="middle" font-size="11" fill="#581c87">2. Elleri toprağa vurup</text>\n  <text x="575" y="216" text-anchor="middle" font-size="11" fill="#581c87">yüzü ve kolları mesh etmek</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">2. ÜNİTE GENEL ÖZETİ: İSLAM\'DA ÜÇ BOYUTLU TEMİZLİK (TAHARET)</text>\n  <rect x="20" y="45" width="210" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">1. Maddi Temizlik</text>\n  <text x="125" y="88" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">(Necasetten Taharet)</text>\n  <text x="125" y="114" text-anchor="middle" font-size="11" fill="#1e3a8a">• Beden temizliği</text>\n  <text x="125" y="136" text-anchor="middle" font-size="11" fill="#1e3a8a">• Elbise temizliği (Müddessir, 4)</text>\n  <text x="125" y="158" text-anchor="middle" font-size="11" fill="#1e3a8a">• İbadet yeri ve ev temizliği</text>\n  <text x="125" y="180" text-anchor="middle" font-size="11" fill="#1e3a8a">• Çevre ve ortak alan temizliği</text>\n  <text x="125" y="210" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">Gözle görülen kirlerin giderilmesi</text>\n\n  <rect x="245" y="45" width="210" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">2. Hükmî Temizlik</text>\n  <text x="350" y="88" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">(Hadesten Taharet)</text>\n  <text x="350" y="114" text-anchor="middle" font-size="11" fill="#14532d">• Küçük hadesten: Abdest</text>\n  <text x="350" y="136" text-anchor="middle" font-size="11" fill="#14532d">• Büyük hadesten: Gusül</text>\n  <text x="350" y="158" text-anchor="middle" font-size="11" fill="#14532d">• Su bulunmadığında: Teyemmüm</text>\n  <text x="350" y="180" text-anchor="middle" font-size="11" fill="#14532d">• Su israfından kaçınma</text>\n  <text x="350" y="210" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">İbadete hazırlık için yapılan arınma</text>\n\n  <rect x="470" y="45" width="210" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#be123c">3. Manevi Temizlik</text>\n  <text x="575" y="88" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">(Kalp ve Ruh Temizliği)</text>\n  <text x="575" y="114" text-anchor="middle" font-size="11" fill="#881337">• Şirk, kibir, haset, riya, gıybet</text>\n  <text x="575" y="132" text-anchor="middle" font-size="11" fill="#881337">ve yalandan uzak durmak</text>\n  <text x="575" y="156" text-anchor="middle" font-size="11" fill="#881337">• İhlas (samimiyet) ve doğruluk</text>\n  <text x="575" y="178" text-anchor="middle" font-size="11" fill="#881337">• Tövbe ve İstiğfar bilinci</text>\n  <text x="575" y="210" text-anchor="middle" font-size="10" font-weight="bold" fill="#be123c">\'Allah tövbe edenleri ve temizlenenleri sever.\'</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
